def calculate_expression(m, n):
    # We assume m < n as per the problem statement
    return (m + n) * abs(n**2 - m**2)

# Test cases for x_n = n
print("Testing x_n = n for small pairs (m, n):")
results = {}
for m in range(1, 6):
    for n in range(m + 1, 7):
        value = calculate_expression(m, n)
        key = (m, n)
        results[key] = value
        print(f"  (m={m}, n={n}): {value}")

min_val = float('inf')
for value in results.values():
    min_val = min(min_val, value)

print(f"\nMinimum value found for x_n = n among these pairs: {min_val}")

